import React, { useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import { toast } from '../libs/toast';
import { Link } from 'react-router-dom';

const toPersianDigits = (str: string | number) => {
  const s = String(str);
  const d = ['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹'];
  return s.replace(/[0-9]/g, (w) => d[+w]);
};

const Estimates: React.FC = () => {
  const [estimates, setEstimates] = useState<any[]>([]);
  const [programs, setPrograms] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [programId, setProgramId] = useState<string>('');
  const token = localStorage.getItem('token');
  const authHeaders = token ? { Authorization: `Bearer ${token}` } : undefined;

  useEffect(() => {
    fetchPrograms();
  }, []);

  useEffect(() => {
    fetchEstimates();
  }, [programId]);

  const fetchPrograms = async () => {
    try {
      const res = await axios.get('/api/programs');
      setPrograms(res.data);
    } catch {
      toast.error('خطا در دریافت برنامه‌ها');
    }
  };

  const fetchEstimates = async () => {
    setLoading(true);
    try {
      const url = programId ? `/api/estimates?program_id=${programId}` : '/api/estimates';
      const res = await axios.get(url);
      setEstimates(res.data);
    } catch {
      toast.error('خطا در دریافت برآوردها');
    } finally {
      setLoading(false);
    }
  };

  const deleteEstimate = async (id: number) => {
    if (!window.confirm('از حذف برآورد مطمئن هستید؟')) return;
    try {
      await axios.delete(`/api/estimates/${id}`, { headers: authHeaders });
      toast.success('برآورد حذف شد');
      fetchEstimates();
    } catch {
      toast.error('حذف برآورد با خطا مواجه شد');
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <h1>برآوردهای برنامه‌ها</h1>
        <Link to="/estimates/new" className="btn btn-primary">ثبت برآورد جدید</Link>
      </div>

      <div className="filters">
        <div className="form-row">
          <label>برنامه</label>
          <select value={programId} onChange={(e) => setProgramId(e.target.value)}>
            <option value="">همه</option>
            {programs.map((p) => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <div className="loading-container"><div className="loading-spinner"></div><p>در حال بارگذاری...</p></div>
      ) : (
        <div className="list-card">
          {estimates.length === 0 ? (
            <p>برآوردی یافت نشد.</p>
          ) : (
            <table className="data-table">
              <thead>
                <tr>
                  <th>کد برآورد</th>
                  <th>برنامه</th>
                  <th>مدت (دقیقه)</th>
                  <th>تعداد برنامه</th>
                  <th>نرخ هر دقیقه</th>
                  <th>مبلغ کل</th>
                  <th>تاریخ ثبت</th>
                  <th>انقضا</th>
                  <th>عملیات</th>
                </tr>
              </thead>
              <tbody>
                {estimates.map((e) => {
                  const totalMinutes = (e.program_count || 0) * (e.duration_minutes || 0);
                  const totalAmount = totalMinutes * (e.minute_rate || 0);
                  const prog = programs.find((p) => p.id === e.program_id);
                  return (
                    <tr key={e.id}>
                      <td>{e.estimate_code}</td>
                      <td>{prog ? prog.name : '—'}</td>
                      <td>{toPersianDigits(e.duration_minutes)}</td>
                      <td>{toPersianDigits(e.program_count)}</td>
                      <td>{toPersianDigits(e.minute_rate)}</td>
                      <td>{toPersianDigits(totalAmount)}</td>
                      <td>{e.created_at?.slice(0, 10) || '—'}</td>
                      <td>{e.expiration_date?.slice(0, 10) || '—'}</td>
                      <td>
                        <Link to={`/estimates/${e.id}`} className="action-btn">جزئیات</Link>
                        <button className="action-btn delete" onClick={() => deleteEstimate(e.id)}>حذف</button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
};

export default Estimates;
